const latestFeedbackForTarget = `-- name: LatestFeedbackForTarget :one
SELECT id, feedback_type
FROM user_feedback
WHERE user_id = $1 AND target_type = $2 AND target_id = $3
ORDER BY created_at DESC, id DESC
LIMIT 1
`

type LatestFeedbackForTargetParams struct {
	UserID     string
	TargetType string
	TargetID   string
}

type LatestFeedbackForTargetRow struct {
	ID           string
	FeedbackType string
}

// 「同一个人对同一行的最后一次表态是什么」。表上刻意没有唯一约束（N2 口径：同一目标
// 可以有多次表态，历史要留），所以 07 §6 的 ErrDuplicateFeedback 只能在领域层判：
// **最近一条就是同一种表态**才算重复提交；中间只要夹过别的表态（先 no、后 yes、
// 再 no），那就是新的信息，不是重复。
func (q *Queries) LatestFeedbackForTarget(ctx context.Context, arg LatestFeedbackForTargetParams) (LatestFeedbackForTargetRow, error) {
	row := q.db.QueryRow(ctx, latestFeedbackForTarget, arg.UserID, arg.TargetType, arg.TargetID)
	var i LatestFeedbackForTargetRow
	err := row.Scan(&i.ID, &i.FeedbackType)
	return i, err
}

