const updatePatternLifecycle = `-- name: UpdatePatternLifecycle :one
UPDATE patterns
SET status = $3,
    confidence = $4,
    evidence_count = $5,
    score_detail = $6,
    last_supported_at = COALESCE($7, last_supported_at),
    confirmed_at = COALESCE($8, confirmed_at),
    rejected_at = COALESCE($9, rejected_at),
    expired_at = COALESCE($10, expired_at),
    reject_reason = $11,
    model_version = $12,
    updated_at = now()
WHERE id = $1 AND user_id = $2
RETURNING id
`

type UpdatePatternLifecycleParams struct {
	ID              string
	UserID          string
	Status          string
	Confidence      pgtype.Numeric
	EvidenceCount   int32
	ScoreDetail     pgtype.Text
	LastSupportedAt pgtype.Timestamptz
	ConfirmedAt     pgtype.Timestamptz
	RejectedAt      pgtype.Timestamptz
	ExpiredAt       pgtype.Timestamptz
	RejectReason    pgtype.Text
	ModelVersion    pgtype.Int8
}

// last_supported_at 用 COALESCE：生命周期转移（确认/削弱/过期）不是「新的支撑观测」，
// 把 NULL 直写进去会抹掉 N3 建立的「最近何时仍被证据支撑」，而 04:231 的
// recent_correction 与 N5 的 freshness 都读它。
func (q *Queries) UpdatePatternLifecycle(ctx context.Context, arg UpdatePatternLifecycleParams) (string, error) {
	row := q.db.QueryRow(ctx, updatePatternLifecycle,
		arg.ID,
		arg.UserID,
		arg.Status,
		arg.Confidence,
		arg.EvidenceCount,
		arg.ScoreDetail,
		arg.LastSupportedAt,
		arg.ConfirmedAt,
		arg.RejectedAt,
		arg.ExpiredAt,
		arg.RejectReason,
		arg.ModelVersion,
	)
	var id string
	err := row.Scan(&id)
	return id, err
}
